window.dadosITI = {
  title: 'Fundamentos de Tecnologia da Informação',
  materiaisUrl: '/profmatheus/materiais/fundamentos-de-ti.html',
  aulas: [
    { icon: '🕰️', t: 'Introdução à TI',
      c: 'Tecnologia da Informação (TI) engloba o uso de computadores, redes, armazenamento e outros recursos para processar e gerenciar informações. A TI moderna combina hardware, software, dados, processos e pessoas para gerar valor nas organizações. Componentes principais: infraestrutura (servidores, redes, data centers), sistemas (ERP, CRM, databases), serviços (suporte, cloud, segurança) e governança (ITIL, COBIT). A área de TI e estrategica para negocios, permitindo automatizacao, tomada de decisao baseada em dados e inovacao digital. O profissional de TI precisa equilibrar conhecimento tecnico com visao de negocios e habilidades interpessoais.',
      a: 'Identifique tres sistemas de TI no seu dia a dia (ex: app de banco, sistema academico, e-commerce) e descreva: qual problema cada um resolve, quais dados processa e qual seria o impacto da sua indisponibilidade por 1 dia.',
      p: 'Pesquise a diferenca entre TI (Tecnologia da Informacao) e TIC (Tecnologias da Informacao e Comunicacao). Quais areas cada uma abrange e como se diferenciam na pratica empresarial?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="30" text-anchor="middle" fill="#4338ca" font-size="13" font-weight="bold">Pilares da TI</text><rect x="20" y="45" width="60" height="35" rx="5" fill="#4338ca"/><text x="50" y="68" text-anchor="middle" fill="#fff" font-size="9">HW</text><rect x="90" y="45" width="60" height="35" rx="5" fill="#059669"/><text x="120" y="68" text-anchor="middle" fill="#fff" font-size="9">SW</text><rect x="160" y="45" width="60" height="35" rx="5" fill="#f59e0b"/><text x="190" y="68" text-anchor="middle" fill="#fff" font-size="9">Dados</text><rect x="230" y="45" width="55" height="35" rx="5" fill="#dc2626"/><text x="257" y="68" text-anchor="middle" fill="#fff" font-size="9">Pessoas</text><rect x="50" y="100" width="200" height="40" rx="6" fill="#1e293b"/><text x="150" y="125" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Processos + Governanca</text><text x="150" y="185" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">TI</text></svg>' },
    { icon: '🖥️', t: 'História da Computação — Pré-história',
      c: 'A historia da computacao comeca muito antes dos computadores eletronicos. O abaco (3000 a.C.) foi o primeiro instrumento de calculo. Blaise Pascal inventou a Pascaline (1642), uma maquina de somar mecanica. Gottfried Leibniz criou a Stepped Reckoner (1672) que multiplicava e dividia. Joseph Marie Jacquard usou cartoes perfurados (1801) para controlar teares, inspirando a programacao futura. Charles Babbage projetou a Maquina Analitica (1837), considerada o primeiro computador, com conceitos de memoria (store) e CPU (mill). Ada Lovelace escreveu o primeiro algoritmo para essa maquina, tornando-se a primeira programadora da historia.',
      a: 'Crie uma linha do tempo visual (papel ou digital) dos marcos da computacao de 3000 a.C. ate 1900. Inclua: abaco, Pascaline, Leibniz, Jacquard, Babbage, Ada Lovelace. Para cada marco, adicione data, inventor e contribuicao principal. Destaque quais conceitos modernos (programacao, memoria, entrada/saida) ja estavam presentes.',
      p: 'Pesquise a historia de Ada Lovelace: qual sua formacao, como conheceu Babbage, por que suas anotacoes sobre a Maquina Analitica sao consideradas o primeiro programa de computador, e qual o impacto do "Ada Lovelace Day" na computacao moderna.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Pre-historia</text><line x1="30" y1="50" x2="270" y2="50" stroke="#4338ca" stroke-width="3"/><circle cx="50" cy="50" r="6" fill="#4338ca"/><text x="50" y="75" text-anchor="middle" fill="#1e293b" font-size="8">Abaco</text><text x="50" y="85" text-anchor="middle" fill="#64748b" font-size="7">3000 aC</text><circle cx="110" cy="50" r="6" fill="#059669"/><text x="110" y="75" text-anchor="middle" fill="#1e293b" font-size="8">Pascaline</text><text x="110" y="85" text-anchor="middle" fill="#64748b" font-size="7">1642</text><circle cx="170" cy="50" r="6" fill="#f59e0b"/><text x="170" y="75" text-anchor="middle" fill="#1e293b" font-size="8">Jacquard</text><text x="170" y="85" text-anchor="middle" fill="#64748b" font-size="7">1801</text><circle cx="240" cy="50" r="6" fill="#dc2626"/><text x="240" y="75" text-anchor="middle" fill="#1e293b" font-size="8">Analitica</text><text x="240" y="85" text-anchor="middle" fill="#64748b" font-size="7">1837</text><rect x="60" y="115" width="180" height="35" rx="6" fill="#1e293b"/><text x="150" y="138" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Ada Lovelace (1843)</text></svg>' },
    { icon: '💡', t: 'Gerações dos Computadores',
      c: 'Computadores evoluiram em gerações marcadas pela tecnologia dos componentes. 1a geracao (1940-1956): valvulas termionicas, gigantescos (ENIAC: 27 toneladas), programacao em linguagem de maquina. 2a geracao (1956-1963): transistores, menores e mais confiaveis, surgem linguagens como FORTRAN e COBOL. 3a geracao (1964-1971): circuitos integrados (CIs), sistemas operacionais, multiprogramacao. 4a geracao (1971-presente): microprocessadores (Intel 4004), computadores pessoais (Apple II, IBM PC), GUI (Macintosh), internet e computacao movel. 5a geracao (emergente): inteligencia artificial, computacao quantica, processamento paralelo massivo.',
      a: 'Pesquise as especificacoes tecnicas do ENIAC (1946) e compare com um smartphone atual. Crie uma tabela com: tamanho, peso, consumo de energia, capacidade de processamento (operacoes/s), memoria e custo ajustado pela inflacao. Calcule quantas vezes o smartphone e mais potente.',
      p: 'Pesquise a Lei de Moore: o que ela previa originalmente, como se manteve por decadas, e por que estudiosos afirmam que esta chegando ao fim. Quais tecnologias podem substituir a litografia atual (ex: computacao quantica, fotônica)?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">5 Geracoes</text><rect x="20" y="35" width="120" height="22" rx="4" fill="#4338ca"/><text x="80" y="50" text-anchor="middle" fill="#fff" font-size="9">1a - Valvulas</text><rect x="160" y="35" width="120" height="22" rx="4" fill="#059669"/><text x="220" y="50" text-anchor="middle" fill="#fff" font-size="9">2a - Transistor</text><rect x="20" y="65" width="120" height="22" rx="4" fill="#f59e0b"/><text x="80" y="80" text-anchor="middle" fill="#fff" font-size="9">3a - Circuitos</text><rect x="160" y="65" width="120" height="22" rx="4" fill="#dc2626"/><text x="220" y="80" text-anchor="middle" fill="#fff" font-size="9">4a - Microproc</text><rect x="60" y="105" width="180" height="30" rx="6" fill="#1e293b"/><text x="150" y="125" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">5a - IA / Quantica</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="11" font-weight="bold">Lei de Moore</text></svg>' },
    { icon: '🏛️', t: 'Marcos do Século XX',
      c: 'O seculo XX foi decisivo para a computacao. Alan Turing (1936) definiu a Maquina de Turing, base teorica de todo computador moderno. Durante a 2a Guerra, Colossus (1943, Turing) decifrava codigos nazistas e ENIAC (1946, Eckert/Mauchly) calculava trajetorias balisticas. John von Neumann formalizou a arquitetura de computador com programa armazenado (1945). A invencao do transistor (Bell Labs, 1947) rendeu o Nobel a Shockley, Bardeen e Brattain. O surgimento do microprocessador Intel 4004 (1971) iniciou a era dos computadores pessoais, culminando no IBM PC (1981) e Apple Macintosh (1984) com interface grafica.',
      a: 'Escolha um dos marcos abaixo e prepare uma apresentacao de 3 minutos: (a) Turing e a Maquina de Turing, (b) ENIAC e as mulheres programadoras, (c) a arquitetura de von Neumann, (d) a criacao do transistor. Inclua contexto historico, personagens e impacto atual.',
      p: 'Pesquise sobre as mulheres pioneiras na computacao: Ada Lovelace, Grace Hopper (criou o primeiro compilador, COBOL), ENIAC girls (Kathleen Antonelli, Jean Bartik, etc.) e Katherine Johnson (NASA). Por que a participacao feminina na computacao diminuiu ao longo do tempo?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Seculo XX</text><rect x="20" y="40" width="125" height="25" rx="4" fill="#4338ca"/><text x="82" y="57" text-anchor="middle" fill="#fff" font-size="9">Turing (1936)</text><rect x="155" y="40" width="125" height="25" rx="4" fill="#059669"/><text x="217" y="57" text-anchor="middle" fill="#fff" font-size="9">ENIAC (1946)</text><rect x="20" y="75" width="125" height="25" rx="4" fill="#f59e0b"/><text x="82" y="92" text-anchor="middle" fill="#fff" font-size="9">Transistor (1947)</text><rect x="155" y="75" width="125" height="25" rx="4" fill="#dc2626"/><text x="217" y="92" text-anchor="middle" fill="#fff" font-size="9">Intel 4004 (1971)</text><rect x="20" y="120" width="260" height="30" rx="6" fill="#1e293b"/><text x="150" y="140" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Arquitetura de von Neumann</text></svg>' },
    { icon: '🌐', t: 'A Internet e a Era Digital',
      c: 'A internet surgiu do projeto ARPANET (1969, DoD EUA), interligando universidades. O protocolo TCP/IP (Cerf e Kahn, 1974) padronizou a comunicacao. Tim Berners-Lee criou a World Wide Web (1989) no CERN com HTML, HTTP e URLs. O primeiro navegador grafico Mosaic (1993) popularizou a web. A era digital trouxe Google (1998), Wikipedia (2001), redes sociais (Facebook 2004, Twitter 2006, Instagram 2010), smartphones (iPhone 2007) e cloud computing (AWS 2006). Hoje, big data e IA transformam a sociedade. O Brasil tinha ~150 milhoes de usuarios de internet em 2023, com acesso principalmente via smartphone.',
      a: 'Crie uma linha do tempo da internet de 1969 a 2020 com pelo menos 15 marcos. Para cada um, inclua: data, criador(es), descricao e impacto. Destaque os marcos que mais influenciam seu dia a dia.',
      p: 'Pesquise a historia da ARPANET: por que foi criada, como era a comunicacao entre os primeiros 4 nos (UCLA, Stanford, UCSB, Utah), o que foi a primeira mensagem enviada ("LOGIN" - que crashou apos "LO"), e como evoluiu para a internet que conhecemos.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><circle cx="80" cy="80" r="25" fill="#4338ca"/><text x="80" y="85" text-anchor="middle" fill="#fff" font-size="9">Web</text><circle cx="150" cy="40" r="25" fill="#059669"/><text x="150" y="45" text-anchor="middle" fill="#fff" font-size="9">TCP/IP</text><circle cx="220" cy="80" r="25" fill="#f59e0b"/><text x="220" y="85" text-anchor="middle" fill="#fff" font-size="9">Mobile</text><circle cx="150" cy="140" r="25" fill="#dc2626"/><text x="150" y="145" text-anchor="middle" fill="#fff" font-size="9">Cloud</text><line x1="105" y1="80" x2="125" y2="40" stroke="#94a3b8" stroke-width="1.5"/><line x1="175" y1="40" x2="195" y2="80" stroke="#94a3b8" stroke-width="1.5"/><line x1="105" y1="80" x2="125" y2="140" stroke="#94a3b8" stroke-width="1.5"/><line x1="195" y1="80" x2="175" y2="140" stroke="#94a3b8" stroke-width="1.5"/><text x="150" y="185" text-anchor="middle" fill="#1e293b" font-size="11" font-weight="bold">ARPANET 1969</text></svg>' },
    { icon: '🖥️', t: 'Hardware — CPU e Memória',
      c: 'O hardware e a parte fisica do computador. A CPU (Unidade Central de Processamento) executa instrucoes: busca (fetch), decodifica e executa. Composta por ALU (aritmetica/logica), UC (controle) e registradores. A memoria hierarquica inclui: registradores (nanossegundos), cache L1/L2/L3 (picossegundos), RAM (nanossegundos) e disco/SSD (micro/milissegundos). A lei de Moore impulsionou o aumento de transistores (Apple M3 Ultra tem ~184 bilhoes). Atualmente, processadores usam multiplos nucleos (dual-core a 128-core) e hyper-threading. A memoria RAM e volatil (dados se perdem sem energia), enquanto armazenamento secundario (SSD, HD) e persistente.',
      a: 'Descubra as especificacoes do seu computador: processador (modelo, nucleos, frequencia), RAM (capacidade, tipo DDR), cache (L1, L2, L3) e armazenamento (HD ou SSD, capacidade). No Windows use "Informacoes do Sistema", no Linux use lscpu e free -h, no macOS use "Sobre Este Mac". Compare com um computador de 10 anos atras.',
      p: 'Pesquise a arquitetura de um processador moderno (ex: Apple M3 ou Intel Core Ultra): litografia (nm), numero de transistores, tipos de nucleo (performance vs eficiencia), cache hierarchy, e tecnologias como AVX, AES-NI e AVX-512. Como essas tecnologias melhoram o desempenho?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Hierarquia de Memoria</text><rect x="80" y="35" width="140" height="22" rx="4" fill="#4338ca"/><text x="150" y="50" text-anchor="middle" fill="#fff" font-size="9">Registradores</text><rect x="60" y="62" width="180" height="22" rx="4" fill="#059669"/><text x="150" y="77" text-anchor="middle" fill="#fff" font-size="9">Cache L1 / L2 / L3</text><rect x="40" y="89" width="220" height="22" rx="4" fill="#f59e0b"/><text x="150" y="104" text-anchor="middle" fill="#fff" font-size="9">RAM (Memoria Principal)</text><rect x="20" y="116" width="260" height="22" rx="4" fill="#dc2626"/><text x="150" y="131" text-anchor="middle" fill="#fff" font-size="9">SSD / HD (Armazenamento)</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="10">Velocidade: ├ r├ípida┤ lenta</text></svg>' },
    { icon: '🔌', t: 'Hardware — Periféricos e Barramentos',
      c: 'Perifericos sao dispositivos que se conectam ao computador para entrada, saida ou ambos. Entrada: teclado, mouse, scanner, microfone, webcam, sensores biometricos. Saida: monitor, impressora, caixas de som, projetor. Entrada/Saida: tela touchscreen, headset, drive optico. A comunicacao entre CPU, memoria e perifericos ocorre via barramentos: PCI Express (GPU, SSD NVMe), USB (universal, ate 40 Gbps USB4), SATA (HD/SSD), HDMI/DisplayPort (video). Controladores como chipset gerenciam o fluxo de dados. A interface Thunderbolt combina PCIe + DisplayPort em um conector. A evolucao dos barramentos busca maior largura de banda e menor latencia.',
      a: 'Identifique todos os perifericos conectados ao seu computador e classifique cada um como entrada, saida ou E/S. Para cada um, identifique o tipo de barramento/conexao (USB, HDMI, Bluetooth, etc.) e a velocidade maxima teorica. Crie uma tabela organizada.',
      p: 'Pesquise a evolucao do barramento USB: versoes (USB 1.0 a USB4), velocidades, tipos de conector (A, B, C, micro, mini), e recursos como Power Delivery (ate 240W) e Thunderbolt. Por que o USB-C esta se tornando padrao universal?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Perifericos</text><rect x="15" y="40" width="85" height="35" rx="5" fill="#4338ca"/><text x="57" y="55" text-anchor="middle" fill="#fff" font-size="8" font-weight="bold">Entrada</text><text x="57" y="67" text-anchor="middle" fill="#e2e8f0" font-size="7">teclado, mouse</text><rect x="108" y="40" width="85" height="35" rx="5" fill="#059669"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="8" font-weight="bold">Saida</text><text x="150" y="67" text-anchor="middle" fill="#e2e8f0" font-size="7">monitor, som</text><rect x="200" y="40" width="85" height="35" rx="5" fill="#f59e0b"/><text x="242" y="55" text-anchor="middle" fill="#fff" font-size="8" font-weight="bold">E/S</text><text x="242" y="67" text-anchor="middle" fill="#e2e8f0" font-size="7">touch, headset</text><rect x="15" y="95" width="270" height="30" rx="6" fill="#1e293b"/><text x="150" y="115" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Barramentos: PCIe | USB | SATA</text><rect x="60" y="140" width="180" height="25" rx="5" fill="#4338ca"/><text x="150" y="157" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">USB-C Universal</text></svg>' },
    { icon: '💻', t: 'Hardware — Dispositivos Móveis e IoT',
      c: 'Dispositivos moveis (smartphones, tablets, wearables) utilizam processadores ARM (Advanced RISC Machine), conhecidos por eficiencia energetica. System-on-a-Chip (SoC) integra CPU, GPU, RAM, modem e sensores em um unico chip (ex: Apple A17, Snapdragon 8 Gen 3, MediaTek Dimensity). IoT (Internet of Things) conecta dispositivos cotidianos a internet: casas inteligentes (termostatos, cameras, lampadas), wearables (Apple Watch, Fitbit), cidades inteligentes (sensores de trafego, iluminacao), industria 4.0 (sensores em maquinas). Espera-se ~30 bilhoes de dispositivos IoT em 2025. A comunicacao IoT usa protocolos como Wi-Fi, Bluetooth LE, Zigbee, LoRaWAN e NB-IoT.',
      a: 'Identifique 5 dispositivos IoT na sua casa ou regiao (ex: smart TV, assistente virtual, camera de seguranca, medidor inteligente, fechadura digital). Para cada um, pesquise: conectividade (Wi-Fi, Bluetooth, Zigbee), protocolo e como melhora (ou nao) a experiencia do usuario.',
      p: 'Pesquise a arquitetura ARM vs x86: diferencas no conjunto de instrucoes (RISC vs CISC), consumo de energia, aplicacoes (mobile vs desktop/servidor). Por que a Apple migrou do Intel x86 para ARM (Apple Silicon) e como a performance se compara?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">IoT - Internet das Coisas</text><rect x="110" y="40" width="80" height="30" rx="6" fill="#4338ca"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Smartphone</text><circle cx="55" cy="105" r="20" fill="#059669"/><text x="55" y="110" text-anchor="middle" fill="#fff" font-size="8">Sensor</text><circle cx="150" cy="105" r="20" fill="#f59e0b"/><text x="150" y="110" text-anchor="middle" fill="#fff" font-size="8">Camera</text><circle cx="245" cy="105" r="20" fill="#dc2626"/><text x="245" y="110" text-anchor="middle" fill="#fff" font-size="8">Smart TV</text><rect x="30" y="145" width="240" height="25" rx="5" fill="#1e293b"/><text x="150" y="162" text-anchor="middle" fill="#fff" font-size="9">Wi-Fi / BLE / Zigbee / LoRa</text></svg>' },
    { icon: '🔧', t: 'Hardware — Montagem e Manutenção',
      c: 'A montagem de um computador desktop envolve selecionar componentes compativeis: placa-mae (socket do processador, chipset), CPU, cooler, RAM (geracao DDR, frequencia), GPU (integrada ou dedicada), SSD/HD (SATA ou NVMe), fonte (potencia calculada) e gabinete (airflow, tamanho). Manutencao preventiva inclui limpeza de poeira, reaplicacao de pasta termica, monitoramento de temperaturas e substituicao de pasta termica. Manutencao corretiva diagnostica problemas: tela azul (Blue Screen), superaquecimento, falha de boot, ruidos no HD. Ferramentas como HWiNFO, CrystalDiskInfo e MemTest86 ajudam no diagnostico.',
      a: 'Simule a montagem de um computador para um orcamento de R$ 4.000 (uso academico/escritorio) e outro de R$ 8.000 (jogos/programacao). Pesquise precos em lojas brasileiras (Kabum, Terabyte, Pichau) e justifique cada componente escolhido, incluindo a compatibilidade entre eles.',
      p: 'Pesquise sobre overclocking: o que e, como funciona (aumento de clock multiplicador/BCLK), riscos (aumento de temperatura, instabilidade, reducao de vida util), e quando vale a pena. Quais processadores Intel (serie K) e AMD (serie X) sao desbloqueados para overclock?',
      req: 'Acesso a sites de hardware (Kabum, Terabyte, Pichau) para pesquisa de precos.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Montagem</text><rect x="30" y="35" width="55" height="40" rx="4" fill="#4338ca"/><text x="57" y="58" text-anchor="middle" fill="#fff" font-size="8">CPU</text><rect x="95" y="35" width="55" height="40" rx="4" fill="#059669"/><text x="122" y="58" text-anchor="middle" fill="#fff" font-size="8">RAM</text><rect x="160" y="35" width="55" height="40" rx="4" fill="#f59e0b"/><text x="187" y="58" text-anchor="middle" fill="#fff" font-size="8">GPU</text><rect x="225" y="35" width="55" height="40" rx="4" fill="#dc2626"/><text x="252" y="58" text-anchor="middle" fill="#fff" font-size="8">SSD</text><rect x="60" y="90" width="180" height="30" rx="6" fill="#1e293b"/><text x="150" y="110" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Placa-mãe + Fonte</text><rect x="80" y="135" width="140" height="25" rx="5" fill="#4338ca"/><text x="150" y="152" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">R$ 4.000 / R$ 8.000</text></svg>' },
    { icon: '🖥️', t: 'Prática: Identificação de Hardware',
      c: 'Aula pratica de laboratorio para identificacao de componentes de hardware. Os alunos aprenderao a abrir um gabinete (com seguranca, desconectado da tomada) e identificar: placa-mae (socket, chipset, slots PCIe/RAM), processador (cooler, pasta termica), modulos de memoria (DDR, capacidade, frequencia), placa de video (GPU, VRAM), armazenamento (HDD vs SSD, SATA vs NVMe), fonte (potencia, cabos) e botoes/conectores do painel frontal (Power, Reset, LED, USB, audio). Ferramentas: chave philips, pulseira antiestatica (ou toque em superficie metalica).',
      a: 'Em grupos, abra um computador desktop (ou examine imagens fornecidas pelo professor) e identifique: modelo do processador, quantidade/tipo de RAM, tipo de armazenamento, modelo da placa-mae e potencia da fonte. Tire fotos e rotule cada componente. Documente em relatorio.',
      p: 'Pesquise sobre a interface NVMe (Non-Volatile Memory Express): como ela difere do SATA em termos de protocolo, latencia e velocidades (PCIe 3.0 x4 vs SATA III). Por que NVMe e muito mais rapido para SSDs?',
      req: 'Gabinete desktop para abertura (ou imagens fornecidas). Chave philips. Pulseira antiestatica (opcional).',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Pratica</text><rect x="40" y="40" width="220" height="120" rx="8" fill="#1e293b"/><rect x="55" y="55" width="40" height="20" rx="3" fill="#4338ca"/><text x="75" y="69" text-anchor="middle" fill="#fff" font-size="7">CPU</text><rect x="105" y="55" width="40" height="20" rx="3" fill="#059669"/><text x="125" y="69" text-anchor="middle" fill="#fff" font-size="7">RAM</text><rect x="155" y="55" width="40" height="20" rx="3" fill="#f59e0b"/><text x="175" y="69" text-anchor="middle" fill="#fff" font-size="7">GPU</text><rect x="205" y="55" width="40" height="20" rx="3" fill="#dc2626"/><text x="225" y="69" text-anchor="middle" fill="#fff" font-size="7">Fonte</text><rect x="55" y="85" width="190" height="20" rx="3" fill="#6366f1"/><text x="150" y="99" text-anchor="middle" fill="#fff" font-size="9">Placa-mae</text><rect x="55" y="115" width="90" height="20" rx="3" fill="#64748b"/><text x="100" y="129" text-anchor="middle" fill="#fff" font-size="8">HDD</text><rect x="155" y="115" width="90" height="20" rx="3" fill="#64748b"/><text x="200" y="129" text-anchor="middle" fill="#fff" font-size="8">SSD</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="10">Gabinete (visao interna)</text></svg>' },
    { icon: '💿', t: 'Software — Conceitos e Classificação',
      c: 'Software e o conjunto de instrucoes logicas que controlam o hardware. Classifica-se em: Software de Sistema (SO, drivers, utilitarios) que gerencia recursos e permite execucao de outros programas; Software Aplicativo (editores de texto, planilhas, navegadores, ERP, CAD) que realiza tarefas do usuario; Software de Programacao (compiladores, editores de codigo, IDEs) usado para criar outros softwares. Quanto a distribuicao: proprietario (licenca paga, codigo fechado - Windows, Office), livre (licenca gratuita, codigo aberto - Linux, Firefox), freeware (gratuito, codigo fechado), shareware (gratuito temporario) e SaaS (software como servico, pago por assinatura - Google Workspace, Office 365).',
      a: 'Liste 10 softwares que voce usa regularmente e classifique cada um em: tipo (sistema, aplicativo, programacao), licenca (proprietario, livre, freeware, SaaS) e plataforma (Windows, Linux, macOS, Web, Mobile). Justifique a classificacao de cada um.',
      p: 'Pesquise as diferencas entre software livre (Free Software, FSF) e codigo aberto (Open Source, OSI). Quais as 4 liberdades do software livre segundo Richard Stallman? compare com a definicao de open source de Eric Raymond. Exemplos praticos de cada.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Classificacao</text><rect x="20" y="40" width="125" height="40" rx="6" fill="#4338ca"/><text x="82" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Sistema</text><text x="82" y="72" text-anchor="middle" fill="#e2e8f0" font-size="8">SO, drivers</text><rect x="155" y="40" width="125" height="40" rx="6" fill="#059669"/><text x="217" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Aplicativo</text><text x="217" y="72" text-anchor="middle" fill="#e2e8f0" font-size="8">Office, browser</text><rect x="20" y="95" width="125" height="40" rx="6" fill="#f59e0b"/><text x="82" y="113" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Programacao</text><text x="82" y="127" text-anchor="middle" fill="#e2e8f0" font-size="8">IDE, compilador</text><rect x="155" y="95" width="125" height="40" rx="6" fill="#dc2626"/><text x="217" y="113" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">SaaS</text><text x="217" y="127" text-anchor="middle" fill="#e2e8f0" font-size="8">por assinatura</text></svg>' },
    { icon: '🔄', t: 'Sistemas Operacionais',
      c: 'Sistema Operacional (SO) e o software mais importante do computador, gerenciando hardware e software. Funcoes: gerenciamento de processos (escalonamento, sincronizacao), memoria (alocacao, paginacao, virtual), arquivos (sistemas de arquivos, permissoes), dispositivos (drivers, E/S) e seguranca (autenticacao, criptografia). Exemplos: Windows (dominante desktop, interface grafica, kernel hibrido), Linux (open source, servidores/cloud, kernel monolitico, diversas distros: Ubuntu, Fedora, Debian), macOS (Unix-based, design integrado Apple, kernel XNU), Android (Linux-based, mobile) e iOS (Unix-based, mobile, kernel XNU). A escolha do SO impacta compatibilidade, seguranca, custo e experiencia do usuario.',
      a: 'Crie uma tabela comparativa entre Windows 11, Ubuntu Linux 24.04 e macOS Sonoma. Compare: kernel, sistema de arquivos padrao, gerenciador de pacotes, requisitos minimos de hardware, mercado-alvo, custo de licenca e principais pontos fortes/fracoes.',
      p: 'Pesquise o que e um kernel: diferencas entre kernel monolitico (Linux), microkernel (Minix), hibrido (Windows, macOS) e exokernel. Vantagens e desvantagens de cada abordagem em termos de desempenho, seguranca e modularidade.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Sistemas Operacionais</text><rect x="25" y="40" width="75" height="40" rx="6" fill="#4338ca"/><text x="62" y="63" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Windows</text><rect x="112" y="40" width="75" height="40" rx="6" fill="#059669"/><text x="150" y="63" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Linux</text><rect x="200" y="40" width="75" height="40" rx="6" fill="#1e293b"/><text x="237" y="63" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">macOS</text><rect x="50" y="100" width="200" height="35" rx="6" fill="#f59e0b"/><text x="150" y="122" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Kernel: Gerencia Tudo</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="10">Processos | Memoria | Arquivos | E/S</text></svg>' },
    { icon: '🛠️', t: 'Software — Aplicativos e Produtividade',
      c: 'Softwares aplicativos sao programas criados para realizar tarefas especificas do usuario. Editores de texto (Word, Google Docs, LibreOffice Writer), planilhas (Excel, Google Sheets, Calc) para analise de dados e graficos, apresentacoes (PowerPoint, Google Slides, Keynote), navegadores web (Chrome, Firefox, Edge, Safari) para acesso a internet, clientes de email (Outlook, Gmail, Thunderbird), ferramentas de colaboracao (Teams, Slack, Zoom, Trello, Notion), editores de imagem/video (Photoshop, GIMP, DaVinci Resolve, Canva) e ERPs (SAP, Oracle, TOTVS) para gestao empresarial integrada. A produtividade e ampliada pela integracao entre ferramentas e automacao de tarefas repetitivas.',
      a: 'Escolha uma tarefa do seu dia a dia (ex: organizar financas pessoais, planejar estudos, gerenciar projetos) e crie um fluxo de trabalho usando pelo menos 3 ferramentas de software diferentes. Descreva como cada ferramenta contribui e como os dados fluem entre elas.',
      p: 'Pesquise sobre suites de produtividade: compare Microsoft 365, Google Workspace e LibreOffice em termos de: custo, funcionalidades offline/online, colaboracao em tempo real, compatibilidade de formatos e suporte a automacao (VBA, Google Apps Script, macros).',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Produtividade</text><rect x="15" y="40" width="85" height="35" rx="5" fill="#4338ca"/><text x="57" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Documentos</text><rect x="108" y="40" width="85" height="35" rx="5" fill="#059669"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Planilhas</text><rect x="200" y="40" width="85" height="35" rx="5" fill="#f59e0b"/><text x="242" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Apresentacao</text><rect x="60" y="95" width="180" height="30" rx="6" fill="#1e293b"/><text x="150" y="115" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Colaboracao (Teams/Slack)</text><rect x="60" y="140" width="180" height="25" rx="5" fill="#dc2626"/><text x="150" y="157" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">ERP / Gestao</text></svg>' },
    { icon: '📊', t: 'Licenciamento e Propriedade Intelectual',
      c: 'Software e protegido por leis de propriedade intelectual. Direitos autorais (copyright) protegem o codigo como obra literaria. Patentes de software protegem invencoes (controverso, variam por pais). Tipos de licenca: proprietaria (uso limitado, codigo fechado, ex: Windows, Photoshop), GPL (General Public License - copyleft, obriga derivados a mesma licenca), MIT/BSD (permissiva, permite uso proprietario), Apache (permissiva com clausula de patentes), Creative Commons (conteudo, nao codigo). Modelos de negocios: venda de licenca, assinatura (SaaS), freemium, open source com suporte pago (Red Hat). Pirataria de software causa prejuizos estimados em ~$50 bilhoes/ano globalmente.',
      a: 'Analise os termos de licenca de 3 softwares que voce usa (ex: Windows, Google Chrome, VS Code, Spotify). Para cada um, identifique: tipo de licenca, permissoes (uso, copia, modificacao, distribuicao), restricoes e modelo de negocios.',
      p: 'Pesquise o caso Oracle vs Google sobre APIs Java no Android: o que a Justica decidiu, por que APIs podem ou nao ser protegidas por direitos autorais, e qual o impacto dessa decisao para o desenvolvimento de software.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Licencas</text><rect x="15" y="40" width="130" height="30" rx="5" fill="#4338ca"/><text x="80" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">GPL (Copyleft)</text><rect x="155" y="40" width="130" height="30" rx="5" fill="#059669"/><text x="220" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">MIT / BSD</text><rect x="15" y="80" width="130" height="30" rx="5" fill="#f59e0b"/><text x="80" y="100" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Proprietaria</text><rect x="155" y="80" width="130" height="30" rx="5" fill="#dc2626"/><text x="220" y="100" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">SaaS</text><rect x="50" y="130" width="200" height="25" rx="5" fill="#1e293b"/><text x="150" y="147" text-anchor="middle" fill="#fff" font-size="10">Creative Commons</text></svg>' },
    { icon: '🗂️', t: 'Dados, Informação e Conhecimento',
      c: 'Dado: fato bruto sem significado isolado (ex: 25, "Joao", "10/01/2024"). Informacao: dado processado e contextualizado que faz sentido (ex: "Joao tem 25 anos e matriculou-se em 10/01/2024"). Conhecimento: informacao aplicada com experiencia, gerando entendimento profundo (ex: "Joao e jovem e ingressou recentemente, provavelmente precisa de orientacao academica inicial"). Sabedoria: conhecimento aplicado com discernimento para tomar decisoes. A piramide DIKW (Data-Information-Knowledge-Wisdom) ilustra essa hierarquia. A gestao da informacao envolve coletar, processar, armazenar, recuperar e disseminar dados de forma eficiente. Big data lida com volumes massivos (3 Vs: Volume, Velocidade, Variedade).',
      a: 'Escolha um cenario do seu cotidiano (ex: processo de matricula, compra online, diagnostico medico) e identifique: quais sao os dados brutos, como sao processados para gerar informacao, que conhecimento pode ser extraido e que sabedoria (decisao) pode ser tomada. Apresente em formato de piramide DIKW.',
      p: 'Pesquise a piramide DIKW: origem do conceito (Russell Ackoff, 1989), criticas ao modelo (a progressao nao e linear), e propostas alternativas mais recentes. Como o conceito de "insight" se encaixa nessa hierarquia?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Piramide DIKW</text><polygon points="150,170 100,130 200,130" fill="#dc2626"/><text x="150" y="145" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Sabedoria</text><polygon points="150,120 70,70 230,70" fill="#f59e0b"/><text x="150" y="90" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Conhecimento</text><polygon points="150,65 40,10 260,10" fill="#059669"/><text x="150" y="30" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Informacao</text><rect x="0" y="175" width="300" height="25" fill="#4338ca"/><text x="150" y="192" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">DADOS</text></svg>' },
    { icon: '🗄️', t: 'Bancos de Dados',
      c: 'Banco de Dados (BD) e uma colecao organizada de dados estruturados. Modelos: relacional (tabelas com linhas e colunas, SQL - MySQL, PostgreSQL), NoSQL (documentos - MongoDB, chave-valor - Redis, grafos - Neo4j, familias de colunas - Cassandra), e novos (NewSQL, time-series, vector DB). SGBD (Sistema de Gerenciamento de BD) prove: armazenamento, consulta (SQL), seguranca (usuarios, permissoes), concorrencia (transacoes ACID), backup e recuperacao. Nos dias de hoje, bancos de dados sao essenciais para aplicacoes web, ERPs, sistemas bancarios, e-commerce e analise de dados. A escolha do banco depende do tipo de dado e dos requisitos de consistencia, escalabilidade e latencia.',
      a: 'Crie um modelo relacional simples para um sistema academico com entidades: Aluno (matricula, nome, email), Professor (codigo, nome, departamento), Disciplina (codigo, nome, creditos), Turma (codigo, professor, semestre) e Matricula (aluno, turma, nota). Identifique chaves primarias e estrangeiras.',
      p: 'Pesquise os principios ACID (Atomicidade, Consistencia, Isolamento, Durabilidade) em transacoes de banco de dados. Explique cada propriedade com um exemplo pratico (ex: transferencia bancaria). Compare com BASE (Basically Available, Soft state, Eventually consistent) usado em NoSQL.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Banco de Dados</text><rect x="15" y="40" width="130" height="35" rx="5" fill="#4338ca"/><text x="80" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">SQL</text><text x="80" y="72" text-anchor="middle" fill="#e2e8f0" font-size="8">Relacional</text><rect x="155" y="40" width="130" height="35" rx="5" fill="#059669"/><text x="220" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">NoSQL</text><text x="220" y="72" text-anchor="middle" fill="#e2e8f0" font-size="8">Documentos/Grafos</text><rect x="50" y="95" width="200" height="35" rx="6" fill="#1e293b"/><text x="150" y="117" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">SGBD</text><rect x="50" y="140" width="200" height="30" rx="5" fill="#6366f1"/><text x="150" y="160" text-anchor="middle" fill="#fff" font-size="10">Transacoes ACID / BASE</text></svg>' },
    { icon: '📶', t: 'Redes de Computadores',
      c: 'Redes de computadores interconectam dispositivos para compartilhar recursos (arquivos, impressoras, internet). Classificacao por alcance: PAN (pessoal, Bluetooth), LAN (local, Wi-Fi/Ethernet), MAN (metropolitana), WAN (geografica, Internet). Topologias: barramento, estrela, anel, malha. Meios: par tranado (Ethernet), fibra optica (alta velocidade, longa distancia), radio (Wi-Fi, 4G/5G). Protocolos principais: TCP/IP (base da Internet), HTTP/HTTPS (web), DNS (nomes), DHCP (configuracao automatica). Enderecamento: IP (logico) e MAC (fisico). Roteadores encaminham pacotes entre redes, switches conectam dispositivos na mesma rede. A Internet e a maior rede WAN do mundo.',
      a: 'Desenhe o diagrama da rede da sua casa ou da escola identificando: modem/roteador, switches (se houver), dispositivos conectados (Wi-Fi e cabo), tipo de conexao (fibra, ADSL, 4G), velocidades contratada e real (fast.com). Classifique cada segmento como LAN ou WAN.',
      p: 'Pesquise o modelo OSI (7 camadas) e o modelo TCP/IP (4 camadas). Descreva a funcao de cada camada e exemplos de protocolos. Por que o modelo TCP/IP se tornou padrao da Internet em vez do OSI?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Redes</text><rect x="60" y="40" width="80" height="35" rx="6" fill="#4338ca"/><text x="100" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">TCP/IP</text><rect x="160" y="40" width="80" height="35" rx="6" fill="#059669"/><text x="200" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">HTTP</text><rect x="40" y="90" width="220" height="30" rx="6" fill="#1e293b"/><text x="150" y="110" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Roteador / Switch</text><circle cx="75" cy="150" r="15" fill="#f59e0b"/><text x="75" y="155" text-anchor="middle" fill="#fff" font-size="8">PC</text><circle cx="150" cy="150" r="15" fill="#dc2626"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="8">Wi-Fi</text><circle cx="225" cy="150" r="15" fill="#6366f1"/><text x="225" y="155" text-anchor="middle" fill="#fff" font-size="8">Serv</text></svg>' },
    { icon: '☁️', t: 'Cloud Computing',
      c: 'Cloud computing oferece recursos de TI sob demanda via internet, pagando pelo uso (pay-as-you-go). Modelos de servico: IaaS (Infraestrutura como Servico: VMs, storage, rede - AWS EC2, Google Compute Engine), PaaS (Plataforma: ambiente de desenvolvimento gerenciado - Heroku, Google App Engine), SaaS (Software: aplicacoes prontas - Google Workspace, Salesforce, Teams). Modelos de implantacao: nuvem publica (AWS, Azure, GCP), privada (datacenter proprio), hibrida (combina publica + privada). Provedores lideres: AWS (~33% mercado), Microsoft Azure (~23%), Google Cloud (~11%). Beneficios: escalabilidade elastica, reducao de CAPEX, alta disponibilidade, disaster recovery, foco no negocio. Desafios: seguranca, custos imprevisiveis, vendor lock-in e latencia.',
      a: 'Crie uma tabela comparativa dos 3 maiores provedores cloud (AWS, Azure, GCP) considerando: fundacao, numero de servicos, regioes globais, modelo de precos, diferencial principal e exemplos de clientes. Pesquise tambem a presenca de cada um no Brasil (regioes Sao Paulo, Rio de Janeiro).',
      p: 'Pesquise o modelo de responsabilidade compartilhada em cloud: o que o provedor gerencia (seguranca DA nuvem: fisica, rede, hypervisor) vs o que o cliente gerencia (seguranca NA nuvem: dados, identidade, configuracao). Como isso varia entre IaaS, PaaS e SaaS?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Cloud Computing</text><rect x="25" y="40" width="75" height="35" rx="6" fill="#4338ca"/><text x="62" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">IaaS</text><rect x="112" y="40" width="75" height="35" rx="6" fill="#059669"/><text x="150" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">PaaS</text><rect x="200" y="40" width="75" height="35" rx="6" fill="#f59e0b"/><text x="237" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">SaaS</text><rect x="25" y="90" width="250" height="30" rx="6" fill="#1e293b"/><text x="150" y="110" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Nuvem: Publica | Privada | Hibrida</text><rect x="25" y="135" width="115" height="30" rx="6" fill="#dc2626"/><text x="82" y="155" text-anchor="middle" fill="#fff" font-size="9">AWS</text><rect x="155" y="135" width="120" height="30" rx="6" fill="#6366f1"/><text x="215" y="155" text-anchor="middle" fill="#fff" font-size="9">Azure / GCP</text></svg>' },
    { icon: '👥', t: 'Peopleware — O Fator Humano',
      c: 'Peopleware refere-se ao papel das pessoas na TI. Um sistema de TI so e bem-sucedido se considerar o fator humano. Aspectos: usabilidade (facilidade de uso, curva de aprendizado, UX design), resistencia a mudanca (medo do novo, falta de treinamento), comunicacao entre equipes tecnicas e negocios, cultura organizacional e gestao de mudanca. O mito do "homem mes" (Brooks, 1975): adicionar pessoas a um projeto atrasado o atrasa mais (curva de aprendizado, comunicacao). A TI precisa de profissionais tecnicos (desenvolvedores, analistas, DBA) e nao-tecnicos (gerentes de projeto, product owners, analistas de negocio, UX designers). Soft skills essenciais: comunicacao, trabalho em equipe, resolucao de problemas e empatia.',
      a: 'Analise um sistema de TI que voce usa (app de banco, portal academico, sistema de RH) sob a otica de peopleware: (1) a interface e intuitiva? (2) como voce se sentiu ao usar pela primeira vez? (3) houve treinamento? (4) o que melhoraria na experiencia do usuario? Escreva um paragrafo de analise.',
      p: 'Pesquise o livro "Peopleware: Productive Projects and Teams" (DeMarco e Lister, 1987/2013): principais ideias sobre produtividade, espaco de trabalho, fluxo, e o conceito de "projeto impossivel". Por que o livro continua relevante 35+ anos depois?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Peopleware</text><circle cx="100" cy="65" r="25" fill="#4338ca"/><text x="100" y="70" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Tecnico</text><circle cx="200" cy="65" r="25" fill="#059669"/><text x="200" y="70" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Negocio</text><rect x="50" y="110" width="200" height="35" rx="6" fill="#f59e0b"/><text x="150" y="132" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Comunicacao + Empatia</text><text x="150" y="178" text-anchor="middle" fill="#4338ca" font-size="10">Soft Skills + Usabilidade</text></svg>' },
    { icon: '🤝', t: 'Peopleware — Equipes e Liderança',
      c: 'Equipes de TI podem ser organizadas de diversas formas: funcional (equipes separadas por especialidade: dev, QA, infra), projeto (multidisciplinar por projeto), matriz (combina ambas), ou squads (agil, times autonomas e multifuncionais). Papeis comuns em equipes ageis: Product Owner (define prioridades do produto), Scrum Master (facilita o processo), Desenvolvedores, QA (testes), DevOps (infraestrutura e deploy). Lideranca em TI vai alem da hierarquia: lideres tecnicos (tech lead) guiam decisoes tecnicas, lideres de pessoas (managers) cuidam do desenvolvimento profissional e bem-estar. A comunicacao eficaz e a gestao de conflitos sao habilidades criticas. Modelos como Tuckman (forming, storming, norming, performing, adjourning) descrevem a maturacao de equipes.',
      a: 'Em grupos de 3-4, simule a formacao de uma startup de TI. Defina: produto, papeis de cada membro (PO, dev, QA, DevOps), metodo de trabalho (Scrum ou Kanban) e ferramentas de comunicacao/gestao. Apresente a estrutura da equipe e justifique as escolhas.',
      p: 'Pesquise o Manifesto Agil (2001): os 4 valores e 12 principios. Como ele surgiu (reuniao de 17 profissionais em Utah), quem participou (Kent Beck, Martin Fowler, Robert C. Martin, etc.), e qual seu impacto na gestao de projetos de TI. Como o \'agil\' se diferencia do metodo cascata (waterfall)?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Equipes Ageis</text><rect x="20" y="40" width="80" height="30" rx="5" fill="#4338ca"/><text x="60" y="60" text-anchor="middle" fill="#fff" font-size="9">Product Owner</text><rect x="110" y="40" width="80" height="30" rx="5" fill="#059669"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="9">Scrum Master</text><rect x="200" y="40" width="80" height="30" rx="5" fill="#f59e0b"/><text x="240" y="60" text-anchor="middle" fill="#fff" font-size="9">Dev Team</text><rect x="40" y="90" width="220" height="30" rx="6" fill="#1e293b"/><text x="150" y="110" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Sprint 1-2 semanas</text><rect x="40" y="135" width="100" height="25" rx="4" fill="#dc2626"/><text x="90" y="152" text-anchor="middle" fill="#fff" font-size="9">Daily (15min)</text><rect x="160" y="135" width="100" height="25" rx="4" fill="#6366f1"/><text x="210" y="152" text-anchor="middle" fill="#fff" font-size="9">Review + Retro</text></svg>' },
    { icon: '🌍', t: 'Sociedade da Informação',
      c: 'Sociedade da Informacao (ou Sociedade do Conhecimento) caracteriza-se pela geracao, processamento e distribuicao intensiva de informacao como atividade economica central. Diferente da sociedade industrial (baseada em manufatura), a sociedade da informacao tem na tecnologia digital seu motor principal. Manuel Castells ("A Sociedade em Rede") descreve uma nova estrutura social baseada em redes digitais que transcendem fronteiras geograficas. A inclusao digital (acesso a internet, dispositivos e habilidades) e condicao para participacao plena nesta sociedade. O Brasil tem ~84% de domicilios com internet (2023), mas desigualdades regionais e socioeconomicas persistem. A exclusao digital aprofunda desigualdades existentes, limitando acesso a educacao, trabalho e servicos publicos.',
      a: 'Pesquise dados sobre inclusao digital no Brasil (TIC Domicilios, Cetic.br). Crie um grafico ou infografico mostrando: % de domicilios com internet por regiao (Norte, Nordeste, Centro-Oeste, Sudeste, Sul), por classe social (A, B, C, D-E) e por area (urbana vs rural). Analise as disparidades.',
      p: 'Pesquise o conceito de "dividendo digital" da ONU: como o acesso a internet pode impulsionar o desenvolvimento economico e social, e quais barreiras (infraestrutura, custo, habilidades, conteudo local) precisam ser superadas para que paises em desenvolvimento colham esses beneficios.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Sociedade da Informacao</text><rect x="40" y="40" width="220" height="120" rx="8" fill="#1e293b"/><circle cx="100" cy="70" r="20" fill="#4338ca"/><text x="100" y="75" text-anchor="middle" fill="#fff" font-size="9">Rede</text><circle cx="200" cy="70" r="20" fill="#059669"/><text x="200" y="75" text-anchor="middle" fill="#fff" font-size="9">Dados</text><circle cx="150" cy="120" r="20" fill="#f59e0b"/><text x="150" y="125" text-anchor="middle" fill="#fff" font-size="9">Pessoas</text><rect x="40" y="160" width="220" height="25" rx="5" fill="#4338ca"/><text x="150" y="177" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Inclusao Digital</text></svg>' },
    { icon: '⚖️', t: 'Ética em TI',
      c: 'A etica em TI aborda dilemas morais relacionados ao uso da tecnologia. Temas principais: privacidade (coleta e uso de dados pessoais - LGPD no Brasil, GDPR na Europa), vigilancia (câmeras, reconhecimento facial, monitoramento de funcionarios), vies algoritmico (IA que discrimina grupos raciais/genero), propriedade intelectual (pirataria, plagio, uso justo), responsabilidade (quem e responsavel quando um sistema falha? carros autonomos?), liberdade de expressao vs moderacao de conteudo (redes sociais), sustentabilidade (lixo eletronico, consumo energetico de data centers). A LGPD (Lei Geral de Protecao de Dados, 2018) regula o tratamento de dados pessoais no Brasil, com multas de ate 2% do faturamento. O profissional de TI deve seguir codigos de etica (ex: ACM, IEEE) e considerar o impacto social de seu trabalho.',
      a: 'Analise um dilema etico real: um desenvolvedor descobre que o sistema de recomendacao da empresa favorece anuncios predatorios para usuarios vulneraveis (ex: idosos em golpes financeiros). O que ele deve fazer? Quais os principios eticos envolvidos? Quais as consequencias de cada acao? Escreva uma reflexao de 1 pagina.',
      p: 'Pesquise o Caso Cambridge Analytica (2018): como dados de ~87 milhoes de usuarios do Facebook foram usados para segmentacao politica, que leis foram violadas, e qual o impacto na regulacao de dados (GDPR, LGPD) e nas politicas de privacidade das big techs.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Etica em TI</text><rect x="20" y="40" width="125" height="35" rx="5" fill="#4338ca"/><text x="82" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Privacidade</text><rect x="155" y="40" width="125" height="35" rx="5" fill="#059669"/><text x="217" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Vies</text><rect x="20" y="85" width="125" height="35" rx="5" fill="#f59e0b"/><text x="82" y="105" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">LGPD/GDPR</text><rect x="155" y="85" width="125" height="35" rx="5" fill="#dc2626"/><text x="217" y="105" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Sustentab.</text><rect x="50" y="140" width="200" height="30" rx="6" fill="#1e293b"/><text x="150" y="160" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Impacto Social</text></svg>' },
    { icon: '🏢', t: 'TI nas Organizações',
      c: 'A TI e estrategica para as organizacoes modernas. Niveis de decisao: operacional (transacoes diarias - sistemas de processamento de transacoes SPT), tatico (gerencia - sistemas de informacao gerencial SIG) e estrategico (direcao - sistemas de apoio a decisao SAD, business intelligence BI). Sistemas integrados: ERP (Enterprise Resource Planning - SAP, Oracle, TOTVS) integra financas, RH, compras, producao; CRM (Customer Relationship Management - Salesforce, HubSpot) gerencia relacionamento com clientes; SCM (Supply Chain Management) gerencia cadeia de suprimentos. A Governanca de TI (ITIL, COBIT) alinha TI aos objetivos de negocios, gerencia riscos e mede desempenho. O CIO (Chief Information Officer) e o executivo responsavel pela estrategia de TI.',
      a: 'Pesquise um ERP disponivel no mercado brasileiro (ex: TOTVS Protheus, Sankhya, Omie, Bling) e analise: modulo principal (financeiro, fiscal, RH, estoque), porte da empresa alvo (micro, pequena, media, grande), modelo de implantacao (on-premise ou cloud), precos e casos de uso.',
      p: 'Pesquise ITIL (Information Technology Infrastructure Library): o que e, sua historia (versoes ITIL v3, ITIL 4), seus principios (foco em valor, progresso iterativo) e as 34 praticas de gestao agrupadas em cadeia de valor, melhoria continua, etc. Como ITIL se relaciona com frameworks ageis (Scrum, DevOps)?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">TI nas Organizacoes</text><rect x="20" y="35" width="80" height="30" rx="5" fill="#4338ca"/><text x="60" y="55" text-anchor="middle" fill="#fff" font-size="9">ERP</text><rect x="110" y="35" width="80" height="30" rx="5" fill="#059669"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="9">CRM</text><rect x="200" y="35" width="80" height="30" rx="5" fill="#f59e0b"/><text x="240" y="55" text-anchor="middle" fill="#fff" font-size="9">SCM</text><rect x="20" y="80" width="260" height="30" rx="6" fill="#1e293b"/><text x="150" y="100" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Governanca: ITIL / COBIT</text><rect x="50" y="130" width="200" height="30" rx="6" fill="#4338ca"/><text x="150" y="150" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">CIO / Estrategia</text></svg>' },
    { icon: '📋', t: 'Projetos de TI',
      c: 'Gerenciamento de projetos de TI aplica conhecimento, habilidades e ferramentas para atingir objetivos dentro de restricoes (escopo, tempo, custo, qualidade). PMBOK (PMI) define 10 areas de conhecimento: integracao, escopo, cronograma, custo, qualidade, recursos, comunicacao, riscos, aquisicoes e stakeholders. Metodologias tradicionais (cascata/waterfall) sao sequenciais: requisitos, design, implementacao, testes, implantacao, manutencao. Metodologias ageis (Scrum, Kanban, XP) sao iterativas e incrementais, adaptando-se a mudancas. Scrum usa sprints (1-4 semanas), papeis (PO, SM, Dev Team) e eventos (sprint planning, daily, review, retrospective). Ferramentas: Jira, Trello, Asana, Microsoft Project. O fracasso de projetos de TI e comum: ~70% dos projetos enfrentam problemas (The Standish Group CHAOS Report). Causas comuns: requisitos mal definidos, falta de comunicacao, mudancas de escopo e estimativas irreais.',
      a: 'Crie o planejamento inicial de um projeto de TI: "Implementacao de um sistema de agendamento de salas para a faculdade". Defina: objetivo, escopo (funcionalidades), cronograma (4 semanas) com marcos, equipe (3 pessoas) e riscos principais. Use o formato de um Product Backlog com historias de usuario.',
      p: 'Pesquise o CHAOS Report do Standish Group: historico (1994-2020+), metodologia de pesquisa, metricas (sucesso, desafiado, fracassado). Como o uso de metodologias ageis impactou as taxas de sucesso ao longo do tempo?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Projetos de TI</text><rect x="30" y="40" width="110" height="40" rx="6" fill="#4338ca"/><text x="85" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Cascata</text><text x="85" y="75" text-anchor="middle" fill="#e2e8f0" font-size="8">sequencial</text><rect x="160" y="40" width="110" height="40" rx="6" fill="#059669"/><text x="215" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Agil (Scrum)</text><text x="215" y="75" text-anchor="middle" fill="#e2e8f0" font-size="8">iterativo</text><rect x="40" y="100" width="220" height="30" rx="6" fill="#1e293b"/><text x="150" y="120" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Escopo / Tempo / Custo</text><rect x="50" y="145" width="200" height="25" rx="5" fill="#f59e0b"/><text x="150" y="162" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Riscos + Qualidade</text></svg>' },
    { icon: '🔐', t: 'Segurança da Informação',
      c: 'Seguranca da Informacao protege a confidencialidade, integridade e disponibilidade (triade CID) dos dados. Confidencialidade: acesso apenas a usuarios autorizados (criptografia, controle de acesso). Integridade: dados nao sao alterados indevidamente (hash, checksum, backup). Disponibilidade: sistemas acessiveis quando necessario (redundancia, disaster recovery). Ameacas comuns: malware (virus, ransomware, worm), phishing (engenharia social), ataques DDoS (sobrecarga), SQL injection, ataques de forca bruta, insider threat (ameaca interna). Defesas: firewall, antivirus, autenticacao multifator (MFA), criptografia (AES, TLS/SSL), backup regular, atualizacoes de seguranca (patches), politicas de senha e treinamento de usuarios. A seguranca e um processo continuo, nao um produto.',
      a: 'Realize um "teste de seguranca" pessoal: (1) suas senhas sao fortes (>=12 caracteres, mistas)? (2) usa a mesma senha em varios sites? (3) tem 2FA ativado onde disponivel? (4) ja clicou em link suspeito? (5) faz backup? Crie um plano de acao para melhorar sua postura de seguranca digital.',
      p: 'Pesquise um ataque cibernetico famoso no Brasil (ex: ataque ao STJ 2020, ransomware na JBS 2021, vazamento do Serasa 2021, ataque a Americanas 2022). Descreva: como ocorreu, qual vetor de ataque, dados comprometidos, impacto financeiro e reputacional, e licoes aprendidas.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Triade CID</text><rect x="30" y="40" width="70" height="50" rx="6" fill="#4338ca"/><text x="65" y="65" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">C</text><text x="65" y="80" text-anchor="middle" fill="#e2e8f0" font-size="8">Confidencial</text><rect x="115" y="40" width="70" height="50" rx="6" fill="#059669"/><text x="150" y="65" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">I</text><text x="150" y="80" text-anchor="middle" fill="#e2e8f0" font-size="8">Integridade</text><rect x="200" y="40" width="70" height="50" rx="6" fill="#f59e0b"/><text x="235" y="65" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">D</text><text x="235" y="80" text-anchor="middle" fill="#e2e8f0" font-size="8">Disponibil.</text><rect x="50" y="115" width="200" height="35" rx="6" fill="#1e293b"/><text x="150" y="138" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Criptografia + MFA</text><rect x="80" y="160" width="140" height="25" rx="5" fill="#dc2626"/><text x="150" y="177" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Backup!</text></svg>' },
    { icon: '🗃️', t: 'Gestão de Dados e Big Data',
      c: 'Big Data refere-se a conjuntos de dados tao grandes ou complexos que ferramentas tradicionais de processamento sao insuficientes. Caracterizado pelos 5 Vs: Volume (terabytes a petabytes), Velocidade (geracao em tempo real - sensores, redes sociais), Variedade (estruturados, semiestruturados, nao estruturados), Veracidade (qualidade e confianca dos dados), Valor (insights de negocios). Tecnologias: Hadoop (HDFS para armazenamento distribuido, MapReduce para processamento), Spark (processamento em memoria, rapido), bancos NoSQL (MongoDB, Cassandra), data lakes (armazenamento bruto) vs data warehouses (dados estruturados para analise, ex: Snowflake, Redshift). ETL (Extract, Transform, Load) integra dados de multiplas fontes. A analise de big data gera insights para negocios, ciencia e governo (ex: Google Trends, Netflix recomendacoes, previsao de epidemias).',
      a: 'Escolha um servico digital que voce usa (Netflix, Spotify, YouTube, Instagram, Google Maps) e analise como ele usa big data: (1) que dados coleta? (2) como processa para gerar recomendacoes? (3) como isso melhora (ou piora) sua experiencia? (4) que questoes de privacidade estao envolvidas?',
      p: 'Pesquise o ecossistema Hadoop: HDFS (sistema de arquivos distribuido), MapReduce (processamento paralelo), YARN (gerenciamento de recursos) e ecosystem tools (Hive, Pig, HBase, Spark). Como o Hadoop possibilitou o processamento de big data em clusters de hardware commodity?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Big Data</text><rect x="15" y="40" width="55" height="35" rx="5" fill="#4338ca"/><text x="42" y="62" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Volume</text><rect x="77" y="40" width="55" height="35" rx="5" fill="#059669"/><text x="104" y="62" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Veloc.</text><rect x="139" y="40" width="55" height="35" rx="5" fill="#f59e0b"/><text x="166" y="62" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Varied.</text><rect x="200" y="40" width="85" height="35" rx="5" fill="#dc2626"/><text x="242" y="55" text-anchor="middle" fill="#fff" font-size="8" font-weight="bold">Veracidade</text><text x="242" y="68" text-anchor="middle" fill="#e2e8f0" font-size="7">+ Valor</text><rect x="50" y="95" width="200" height="35" rx="6" fill="#1e293b"/><text x="150" y="117" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Hadoop / Spark</text><rect x="50" y="145" width="200" height="25" rx="5" fill="#4338ca"/><text x="150" y="162" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Data Lake / Warehouse</text></svg>' },
    { icon: '🤖', t: 'Inteligência Artificial',
      c: 'Inteligencia Artificial (IA) e a capacidade de maquinas simularem inteligencia humana. Subareas: Machine Learning (algoritmos que aprendem com dados - regressao, arvores de decisao, SVM), Deep Learning (redes neurais profundas - CNNs para imagens, RNNs/Transformers para texto), Processamento de Linguagem Natural (PLN - chatbots, traducao, analise de sentimentos), Visao Computacional (reconhecimento facial, diagnostico por imagem), Sistemas Especialistas (regras baseadas em conhecimento). IA generativa (ChatGPT, Gemini, Copilot, Midjourney, DALL-E) cria conteudo novo (texto, imagem, codigo, musica). Grandes empresas investem pesado: OpenAI, Google DeepMind, Meta AI. A IA levanta questoes eticas: vies, desemprego, uso em armas autonomas, privacidade, alucinacoes (respostas incorretas com confianca).',
      a: 'Use um chatbot de IA generativa (ChatGPT, Gemini, Copilot) para realizar uma tarefa academica (ex: resumir um texto, explicar um conceito, gerar um código simples). Avalie: (1) a resposta foi correta? (2) como voce verificou a qualidade? (3) houve alucinacao? (4) o que voce aprendeu sobre os limites da ferramenta?',
      p: 'Pesquise como funciona um Transformer (arquitetura "Attention is All You Need", Google 2017): atencao multi-cabeca, posicional encoding, encoder-decoder. Como os LLMs (Large Language Models) como GPT-4 sao treinados (pre-treino, fine-tuning, RLHF)?',
      req: 'Acesso a um chatbot de IA (ChatGPT, Gemini, Copilot) para teste.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Inteligencia Artificial</text><rect x="60" y="40" width="80" height="30" rx="6" fill="#4338ca"/><text x="100" y="60" text-anchor="middle" fill="#fff" font-size="9">Machine Learning</text><rect x="160" y="40" width="80" height="30" rx="6" fill="#059669"/><text x="200" y="60" text-anchor="middle" fill="#fff" font-size="9">Deep Learning</text><rect x="60" y="80" width="80" height="30" rx="6" fill="#f59e0b"/><text x="100" y="100" text-anchor="middle" fill="#fff" font-size="9">PLN</text><rect x="160" y="80" width="80" height="30" rx="6" fill="#dc2626"/><text x="200" y="100" text-anchor="middle" fill="#fff" font-size="9">Visao</text><rect x="40" y="130" width="220" height="35" rx="6" fill="#1e293b"/><text x="150" y="152" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">IA Generativa (LLMs)</text></svg>' },
    { icon: '🔄', t: 'Transformação Digital',
      c: 'Transformacao Digital e a integracao de tecnologia digital em todas as areas de uma organizacao, mudando fundamentalmente como ela opera e entrega valor. Nao se trata apenas de adotar tecnologia, mas de repensar processos, cultura e modelo de negocios. Elementos: digitalizacao (converter analogico para digital - ex: scanner), digitalizacao de processos (automatizar processos manuais) e transformacao digital (criar novos modelos de negocios digitais - ex: Uber, Netflix, iFood, Nubank). Tecnologias habilitadoras: cloud, mobile, IA, IoT, big data, blockchain. Exemplos: varejo omnicanal, banco digital (Nubank sem agencias), saude digital (telemedicina, prontuarios eletronicos), educacao (EAD, plataformas adaptativas). A pandemia de COVID-19 acelerou a transformacao digital em anos. Desafios: cultura organizacional, resistencia a mudanca, legacy systems, seguranca e custos.',
      a: 'Escolha uma empresa tradicional (ex: Banco do Brasil, Magazine Luiza, Volkswagen) e analise sua jornada de transformacao digital. Identifique: (1) o que mudou no modelo de negocios, (2) que tecnologias foram adotadas, (3) quais desafios enfrentou e (4) quais resultados obteve. Apresente em formato de estudo de caso.',
      p: 'Pesquise o conceito de "destruicao criativa" de Schumpeter aplicado a TI: como empresas inovadoras (startups) desafiam incumbentes com modelos digitais. Exemplos: Netflix vs Blockbuster, Airbnb vs hoteis, Uber vs taxis, Nubank vs bancos tradicionais. Qual o padrao comum?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Transformacao Digital</text><rect x="20" y="40" width="85" height="35" rx="5" fill="#4338ca"/><text x="62" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Digitalizar</text><rect x="115" y="40" width="85" height="35" rx="5" fill="#059669"/><text x="157" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Automatizar</text><rect x="210" y="40" width="75" height="35" rx="5" fill="#f59e0b"/><text x="247" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Inovar</text><rect x="40" y="95" width="220" height="35" rx="6" fill="#1e293b"/><text x="150" y="117" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Novo Modelo de Negocio</text><rect x="60" y="145" width="180" height="25" rx="5" fill="#4338ca"/><text x="150" y="162" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Cloud + IA + IoT</text></svg>' },
    { icon: '🔄', t: 'Carreiras em TI',
      c: 'O mercado de TI no Brasil e um dos que mais cresce, com saldos positivos de empregos formais. Principais carreiras: Desenvolvimento (frontend, backend, mobile, full stack), Infraestrutura (redes, cloud, DevOps, SRE), Dados (analista, cientista, engenheiro de dados), Seguranca (analista SOC, pentester, engenheiro de seguranca), Gestao (gerente de projetos, PO, Scrum Master, CIO), Qualidade (QA, analista de testes, automacao), Produto (Product Manager, Product Owner). Salarios variam por regiao, experiencia e especializacao. Certificacoes valorizadas: cloud (AWS Solutions Architect, Azure Administrator), seguranca (CISSP, CEH), gestao (PMP, ITIL, CSM). Soft skills cada vez mais importantes: comunicacao, trabalho em equipe, aprendizado continuo (lifelong learning). Portfolios no GitHub, contribuicoes open source e projetos pessoais contam muito em processos seletivos.',
      a: 'Pesquise uma carreira de TI que te interessa. Encontre 3 vagas reais (LinkedIn, Glassdoor, GeekHunter) e analise: (1) requisitos tecnicos, (2) soft skills exigidas, (3) faixa salarial, (4) tipo de contratacao (CLT, PJ), (5) empresa e setor. Crie um plano de 6 meses para adquirir as habilidades que faltam.',
      p: 'Pesquise o portal "roadmap.sh" e escolha um roadmap de carreira (ex: Frontend, Backend, DevOps, Data Science). Identifique: quais tecnologias sao fundamentais vs boas de saber, a ordem recomendada de aprendizado, e recursos (cursos, livros) sugeridos para cada etapa.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Carreiras em TI</text><rect x="15" y="40" width="85" height="30" rx="5" fill="#4338ca"/><text x="57" y="60" text-anchor="middle" fill="#fff" font-size="9">Dev</text><rect x="108" y="40" width="85" height="30" rx="5" fill="#059669"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="9">Infra</text><rect x="200" y="40" width="85" height="30" rx="5" fill="#f59e0b"/><text x="242" y="60" text-anchor="middle" fill="#fff" font-size="9">Dados</text><rect x="15" y="80" width="85" height="30" rx="5" fill="#dc2626"/><text x="57" y="100" text-anchor="middle" fill="#fff" font-size="9">Seguranca</text><rect x="108" y="80" width="85" height="30" rx="5" fill="#6366f1"/><text x="150" y="100" text-anchor="middle" fill="#fff" font-size="9">Gestao</text><rect x="200" y="80" width="85" height="30" rx="5" fill="#1e293b"/><text x="242" y="100" text-anchor="middle" fill="#fff" font-size="9">QA</text><rect x="50" y="135" width="200" height="30" rx="6" fill="#4338ca"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Portfolio + GitHub</text></svg>' },
    { icon: '📱', t: 'Tendências — Computação Móvel',
      c: 'A computacao movel domina o acesso a internet: ~60% do trafego web global vem de dispositivos moveis. Smartphones evoluem rapidamente: processadores (Apple A17 Pro, Snapdragon 8 Gen 3), cameras computacionais (iPhone 15 Pro Max, Samsung Galaxy S24 Ultra), telas dobráveis (Samsung Galaxy Z Fold, Motorola Razr), 5G (velocidades ate 10 Gbps, baixa latencia). Aplicacoes移动: mobile banking (Pix revolucionou pagamentos no Brasil), delivery (iFood, Uber Eats), transporte (Uber, 99), redes sociais (TikTok, Instagram, WhatsApp), saude (apps de telemedicina, monitors Apple Watch). A computacao movel impulsiona a tendencia "mobile-first" no design de produtos digitais. A Apple e Samsung lideram o mercado premium, enquanto Xiaomi e Transsion dominam o segmento de entrada. O ecossistema de apps movel movimenta ~$500 bilhoes/ano globalmente.',
      a: 'Analise o impacto do Pix no Brasil: como a tecnologia mobile banking mudou os habitos financeiros dos brasileiros? Pesquise dados de adocao do Pix (quantidade de transacoes, usuarios, valores movimentados) e compare com metodos anteriores (DOC/TED, boleto, dinheiro).',
      p: 'Pesquise a evolucao das redes moveis: 1G a 5G (e 6G emergente). Para cada geracao, qual a tecnologia, velocidades tipicas, latencia, e principais aplicacoes habilitadas. O que o 5G promete para IoT, carros autonomos, cirurgia remota e realidade aumentada?',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Computacao Movel</text><rect x="80" y="40" width="140" height="70" rx="8" fill="#1e293b"/><rect x="100" y="55" width="100" height="25" rx="4" fill="#4338ca"/><text x="150" y="72" text-anchor="middle" fill="#fff" font-size="12" font-weight="bold">Smartphone</text><rect x="100" y="85" width="100" height="18" rx="3" fill="#059669"/><text x="150" y="98" text-anchor="middle" fill="#fff" font-size="9">5G</text><text x="150" y="140" text-anchor="middle" fill="#4338ca" font-size="10">Mobile Banking / Pix</text><rect x="50" y="155" width="200" height="25" rx="5" fill="#4338ca"/><text x="150" y="172" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Mobile-First</text></svg>' },
    { icon: '🏠', t: 'Tendências — IoT e Cidades Inteligentes',
      c: 'Cidades inteligentes (smart cities) usam IoT, dados e TI para melhorar qualidade de vida, sustentabilidade e eficiencia dos servicos urbanos. Exemplos: iluminacao publica inteligente (sensores de presenca, LED), gestao de trafego (semafaros adaptativos, Waze), coleta de lixo (lixeiras com sensor de enchimento), medidores inteligentes (agua, energia), estacionamento (sensores de vaga), monitoramento ambiental (qualidade do ar, ruido), seguranca (cameras com analise de video). A Cisco estima que soluções de cidades inteligentes podem melhorar a eficiencia urbana em 15-30%. Desafios: infraestrutura de conectividade (5G, LoRaWAN), interoperabilidade entre sistemas, privacidade dos dados dos cidadaos, investimento inicial e capacitacao de gestores publicos. O Brasil tem iniciativas em Curitiba, Sao Paulo, Rio de Janeiro e Florianopolis.',
      a: 'Identifique um problema urbano na sua cidade (ex: transito, iluminacao, coleta de lixo, seguranca) e proponha uma solucao baseada em IoT/TI. Descreva: (1) sensores necessarios, (2) conectividade, (3) processamento de dados, (4) acao resultante e (5) metricas de sucesso.',
      p: 'Pesquise sobre o conceito de "digital twin" (gemeo digital) aplicado a cidades: como a simulacao computacional de uma cidade pode ajudar no planejamento urbano, previsao de desastres e gestao de recursos. Exemplos reais: Singapore Virtual Singapore, Barcelona Digital City.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Cidades Inteligentes</text><rect x="15" y="40" width="55" height="40" rx="4" fill="#4338ca"/><text x="42" y="60" text-anchor="middle" fill="#fff" font-size="8">Sensor</text><rect x="80" y="40" width="55" height="40" rx="4" fill="#059669"/><text x="107" y="60" text-anchor="middle" fill="#fff" font-size="8">Rede</text><rect x="145" y="40" width="55" height="40" rx="4" fill="#f59e0b"/><text x="172" y="60" text-anchor="middle" fill="#fff" font-size="8">Dados</text><rect x="210" y="40" width="75" height="40" rx="4" fill="#dc2626"/><text x="247" y="58" text-anchor="middle" fill="#fff" font-size="8">Acao</text><rect x="40" y="100" width="220" height="35" rx="6" fill="#1e293b"/><text x="150" y="122" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Cidade Conectada</text><rect x="60" y="150" width="180" height="25" rx="5" fill="#4338ca"/><text x="150" y="167" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Qualidade de Vida</text></svg>' },
    { icon: '🔮', t: 'Tendências — Futuro da TI',
      c: 'O futuro da TI promete transformacoes profundas. Computacao quantica: usa qubits (superposicao, entrelacamento) para resolver problemas intrataveis para computadores classicos (criptografia, quimica, otimizacao). Empresas: IBM (Quantum System One), Google (Sycamore), D-Wave. Computacao em borda (edge computing): processa dados perto da fonte (sensores, cameras) reduzindo latencia e banda, essencial para IoT e carros autonomos. Realidade estendida (XR): VR (realidade virtual - Meta Quest, Apple Vision Pro), AR (aumentada - HoloLens, filtros Instagram), MR (mista). Blockchain alem de criptomoedas: contratos inteligentes, DeFi, NFTs, rastreabilidade de cadeias de suprimentos, identidade digital autonomia (Self-Sovereign Identity). Tecnologias verdes (Green IT): data centers sustentaveis (energia renovavel, refrigeracao), computacao de baixo consumo, reciclagem de lixo eletronico.',
      a: 'Crie um cenario futuro (2035) para a TI. Escolha 3 tendencias (computacao quantica, edge computing, XR, blockchain, Green IT) e descreva: (1) como cada uma amadureceu, (2) que problemas resolve, (3) como impacta o dia a dia das pessoas e (4) que novos desafios eticos/sociais surgem. Seja criativo mas baseado em pesquisas reais.',
      p: 'Pesquise o "vale da estranheza" (uncanny valley) em RV/RA: o que e, como afeta a aceitacao de avatares realistas, e como empresas como Meta e Apple estao lidando com isso no design de seus dispositivos (Quest 3, Vision Pro).',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Futuro da TI</text><rect x="15" y="40" width="85" height="35" rx="5" fill="#4338ca"/><text x="57" y="60" text-anchor="middle" fill="#fff" font-size="9">Quantica</text><rect x="108" y="40" width="85" height="35" rx="5" fill="#059669"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="9">Edge</text><rect x="200" y="40" width="85" height="35" rx="5" fill="#f59e0b"/><text x="242" y="60" text-anchor="middle" fill="#fff" font-size="9">XR</text><rect x="15" y="85" width="130" height="35" rx="5" fill="#dc2626"/><text x="80" y="105" text-anchor="middle" fill="#fff" font-size="9">Blockchain</text><rect x="155" y="85" width="130" height="35" rx="5" fill="#1e293b"/><text x="220" y="105" text-anchor="middle" fill="#fff" font-size="9">Green IT</text><rect x="40" y="140" width="220" height="30" rx="6" fill="#4338ca"/><text x="150" y="160" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">2035: Convergencia</text></svg>' },
    { icon: '📖', t: 'Revisão Geral',
      c: 'Revisao integrada de todo o conteudo do semestre: historia da computacao (geracoes, marcos, personagens), hardware (CPU, memoria, perifericos, barramentos), software (classificacao, SO, licencas), dados/informacao/conhecimento (piramide DIKW, bancos de dados, big data), peopleware (fator humano, equipes ageis), sociedade da informacao (inclusao digital, etica), arquitetura de computadores, sistemas de informacao (ERP, CRM, governanca), redes e internet, seguranca (triade CID, ameacas), cloud computing, tendencias (IA, IoT, transformacao digital, carreiras). Mapa mental conectando todos os topicos. Esclarecimento de duvidas.',
      a: 'Crie um mapa mental (conceitual) conectando TODOS os topicos da disciplina. Identifique relacoes entre eles (ex: como big data se relaciona com IA e cloud? como seguranca se relaciona com todas as areas?). Use ferramenta digital (MindMeister, XMind, Miro) ou papel colorido.',
      p: 'Identifique os 3 topicos que voce mais gostou e os 3 que teve mais dificuldade. Para cada um, pesquise um recurso adicional (video, artigo, livro, curso) para aprofundamento e anote para estudos futuros.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><circle cx="150" cy="50" r="25" fill="#4338ca"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">TI</text><line x1="130" y1="65" x2="80" y2="100" stroke="#4338ca" stroke-width="1.5"/><line x1="170" y1="65" x2="220" y2="100" stroke="#4338ca" stroke-width="1.5"/><line x1="150" y1="75" x2="150" y2="100" stroke="#4338ca" stroke-width="1.5"/><rect x="15" y="100" width="80" height="30" rx="5" fill="#059669"/><text x="55" y="120" text-anchor="middle" fill="#fff" font-size="8">Hardware</text><rect x="110" y="100" width="80" height="30" rx="5" fill="#f59e0b"/><text x="150" y="120" text-anchor="middle" fill="#fff" font-size="8">Software</text><rect x="205" y="100" width="80" height="30" rx="5" fill="#dc2626"/><text x="245" y="120" text-anchor="middle" fill="#fff" font-size="8">Dados</text><rect x="60" y="145" width="180" height="30" rx="6" fill="#1e293b"/><text x="150" y="165" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Pessoas + Processos</text></svg>' },
    { icon: '📝', t: 'Exercícios de Preparação',
      c: 'Ultima revisao antes da prova final. Resolucao de exercicios abrangentes que cobrem todo o semestre: (1) identificar geracoes de computadores, (2) classificar hardware/software, (3) aplicar piramide DIKW a um cenario, (4) calcular enderecos IP e sub-redes, (5) identificar ameacas de seguranca e defesas, (6) explicar diferenca entre IaaS/PaaS/SaaS, (7) descrever ciclo de vida de projeto agil, (8) analisar dilema etico em TI. Esclarecimento de duvidas finais. Dicas de estudo e estrategia de prova.',
      a: 'Resolva uma prova simulada com 10 questoes cobrindo todos os topicos do semestre em 50 minutos. Inclui questoes objetivas, discursivas e estudo de caso. Cronometre o tempo.',
      p: 'Identifique seus ultimos pontos fracos e faca uma revisao focada nas areas identificadas. Use o mapa mental criado na aula anterior como guia de estudo.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Preparacao</text><rect x="30" y="40" width="240" height="120" rx="8" fill="#1e293b"/><rect x="45" y="55" width="210" height="6" rx="3" fill="#4338ca"/><rect x="45" y="70" width="180" height="6" rx="3" fill="#059669"/><rect x="45" y="85" width="200" height="6" rx="3" fill="#f59e0b"/><rect x="45" y="100" width="160" height="6" rx="3" fill="#dc2626"/><rect x="45" y="115" width="190" height="6" rx="3" fill="#6366f1"/><text x="150" y="145" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Prova Simulada - 50 min</text><text x="150" y="182" text-anchor="middle" fill="#4338ca" font-size="10">10 questoes - Todos os topicos</text></svg>' },
    { icon: '📝', t: 'Prova Final',
      c: 'Avaliacao final individual de todo o conteudo do semestre. Questoes discursivas, analise de cenarios, identificacao de conceitos e questoes de multipla escolha. Duracao: 100 minutos (2 aulas). Valor: 10 pontos. Conteudo: historia da computacao, hardware, software, dados/informacao/conhecimento, peopleware, sociedade da informacao, arquitetura, sistemas de informacao, redes, seguranca, cloud, tendencias. Nao e permitido uso de dispositivos eletronicos. Material de consulta: nenhum (exceto se previamente combinado).',
      a: 'Leia todas as questoes antes de comecar. Gerencie o tempo: comece pelas questoes que voce domina. Responda com clareza e exemplos. Revise antes de entregar.',
      p: 'Apos a prova, faca uma autoavaliacao do seu aprendizado: o que voce aprendeu de mais valioso, como pretende aplicar esse conhecimento no curso e na carreira, e que topicos quer aprofundar.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="25" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Prova Final</text><rect x="50" y="40" width="200" height="120" rx="8" fill="#4338ca"/><text x="150" y="70" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">100</text><text x="150" y="90" text-anchor="middle" fill="#e2e8f0" font-size="10">minutos</text><rect x="65" y="105" width="170" height="3" rx="1" fill="#f59e0b"/><text x="150" y="125" text-anchor="middle" fill="#e2e8f0" font-size="10">10 questoes</text><text x="150" y="140" text-anchor="middle" fill="#e2e8f0" font-size="10">Todo o conteudo</text><text x="150" y="182" text-anchor="middle" fill="#4338ca" font-size="10" font-weight="bold">Boa prova!</text></svg>' },
    { icon: '🎓', t: 'Encerramento',
      c: 'Encerramento da disciplina ITI-001 - Fundamentos de Tecnologia da Informacao. Vista de prova com correcao comentada e esclarecimento de duvidas sobre a correcao. Divulgacao das notas finais e medias. Feedback dos alunos: o que funcionou bem, sugestoes de melhoria para proximas turmas (conteudo, metodologia, avaliacao, material didatico). Discussao sobre a importancia dos fundamentos de TI para as demais disciplinas do curso (programacao, redes, banco de dados, engenharia de software). Orientacao sobre carreira e caminhos de especializacao. Consideracoes finais do professor.',
      a: 'Participe da avaliacao da disciplina com feedback construtivo sobre: conteudo, metodologia, material didatico, atividades praticas e avaliacoes. Deixe sugestoes para melhoria.',
      p: 'Reflita sobre como os conceitos de TI se conectam com as outras disciplinas do curso e crie um plano pessoal de estudos para o proximo semestre, identificando areas de interesse para aprofundamento.',
      svg: '<svg viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="30" text-anchor="middle" fill="#4338ca" font-size="16" font-weight="bold">ITI-001</text><rect x="60" y="50" width="180" height="30" rx="6" fill="#4338ca"/><text x="150" y="70" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Fundamentos de TI</text><rect x="60" y="90" width="180" height="30" rx="6" fill="#059669"/><text x="150" y="110" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Notas Finais</text><rect x="60" y="130" width="180" height="30" rx="6" fill="#f59e0b"/><text x="150" y="150" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Feedback da Turma</text><text x="150" y="185" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">FIM</text></svg>' }
  ]
};
